// Example tag analysis usage
function getTopProfessorTags() {
    return fetch('/professor_tags_analysis.json')
        .then(r => r.json())
        .then(data => {
            // Get most common tags
            const sortedTags = Object.entries(data.tag_frequency)
                .sort(([,a], [,b]) => b - a)
                .slice(0, 10);
            return sortedTags;
        });
}
